import{c as a,$ as r,Q as s,j as n,g as e,o,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const k=JSON.parse('{"title":"Маркетплейс модулей","description":"Практическое руководство по каталогу расширений ОмниКрафт ЕРП, подключению бесплатных и платных модулей, архитектуре ленивой загрузки и изоляции баз данных.","frontmatter":{"title":"Маркетплейс модулей","description":"Практическое руководство по каталогу расширений ОмниКрафт ЕРП, подключению бесплатных и платных модулей, архитектуре ленивой загрузки и изоляции баз данных.","datePublished":"2026-10-28","dateModified":"2026-11-19","order":21},"headers":[],"relativePath":"ru/docs/spaces/marketplace.md","filePath":"ru/docs/spaces/marketplace.md","lastUpdated":1795046400000}'),c={name:"ru/docs/spaces/marketplace.md"},h={id:"маркетплеис-модулеи-экосистема-специализированных-расширении",tabindex:"-1"};function g(p,t,u,x,y,b){const l=r("DocIcon");return s(),n("div",null,[e("h1",h,[o(l,{name:"marketplace"}),t[0]||(t[0]=i(" Маркетплейс модулей: Экосистема специализированных расширений ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#маркетплеис-модулеи-экосистема-специализированных-расширении","aria-label":'Permalink to "Маркетплейс модулей: Экосистема специализированных расширений"'},"​",-1))]),t[2]||(t[2]=d('<p>Деятельность ремесленника, сервисного инженера или владельца студии индивидуального пошива слишком многогранна, чтобы пытаться уместить её в один перегруженный монолитный экран. Специфический инструмент, жизненно необходимый кожевнику (расчет площади шкур или учет шага пробойников), окажется бесполезным балластом для часового мастера или мастера по ремонту электроники, перегружая визуальное пространство кнопками и замедляя работу.</p><p>Для решения этой задачи в ОмниКрафт ЕРП реализована архитектура <strong>сквозных модулей и встроенного каталога расширений (Маркетплейс)</strong>:</p><ul><li><strong>Легковесное чистое ядро:</strong> базовый каркас программы содержит только фундаментальные контуры (активы, склад, движение денег, управленческий баланс, продажи и онлайн-витрину);</li><li><strong>Точечная специализация:</strong> мастер самостоятельно выбирает и подключает узкоотраслевые расширения, необходимые именно его ремеслу;</li><li><strong>Сквозная доступность:</strong> в отличие от цеховых складов или технологических карт, жестко привязанных к конкретному производству, подключенные модули работают поверх всех рабочих пространств и сохраняют свои базы данных независимо от смены направлений.</li></ul><hr><h2 id="архитектура-маркетплеиса-как-устроен-каталог-в-программе" tabindex="-1">Архитектура Маркетплейса: как устроен каталог в программе <a class="header-anchor" href="#архитектура-маркетплеиса-как-устроен-каталог-в-программе" aria-label="Permalink to &quot;Архитектура Маркетплейса: как устроен каталог в программе&quot;">​</a></h2><p>Вход в каталог осуществляется в один клик: на правой боковой панели или через выпадающее меню программы выберите пункт <strong>«Маркетплейс модулей»</strong>.</p><p>Программа открывает диалоговое окно со списком доступных расширений, загружая актуальную структуру каталога через защищенный сетевой шлюз:</p><div class="craft-window-frame" data-title="Маркетплейс модулей расширения"><div style="padding:1rem 1.25rem;"><table class="craft-matrix-table" style="margin:0;"><thead><tr><th style="width:45%;">Модуль расширения</th><th style="width:35%;">Функциональные возможности</th><th style="width:20%;">Статус</th></tr></thead><tbody><tr><td><strong>Модуль «Амбассадор»</strong></td><td>Партнёрский маркетинг, реферальные ссылки, QR-коды на чеках и сквозная аналитика.</td><td><span style="color:#10b981;font-weight:600;">● Установлено</span></td></tr><tr><td><strong>Проектирование и лекала</strong></td><td>Раскрой листовых материалов, расчёт технологических припусков и библиотека карт.</td><td><span style="opacity:0.85;">2 900 ₽</span></td></tr><tr><td><strong>Интеграция со службами доставки</strong></td><td>Печать транспортных накладных, расчёт тарифов и автоматический трекинг посылок.</td><td><span style="opacity:0.85;">1 900 ₽</span></td></tr></tbody></table></div></div><h3 id="отказоустоичивость-и-работа-при-нестабильнои-сети" tabindex="-1">Отказоустойчивость и работа при нестабильной сети <a class="header-anchor" href="#отказоустоичивость-и-работа-при-нестабильнои-сети" aria-label="Permalink to &quot;Отказоустойчивость и работа при нестабильной сети&quot;">​</a></h3><p>В ОмниКрафт ЕРП заложен строгий принцип автономии: программа никогда не блокирует работу мастера при сетевых неполадках:</p><ul><li><strong>Кэширование в оперативной памяти:</strong> однажды загруженный каталог сохраняется в памяти приложения. Если интернет-соединение временно прервалось, система моментально отображает закэшированный список без задержек;</li><li><strong>Информативный экран восстановления:</strong> при возникновении сетевого таймаута на первом запуске открывается вежливое уведомление со значком отключенной сети и кнопкой <strong>«Повторить попытку»</strong>.</li></ul><hr><h2 id="статусы-карточек-и-правила-подключения-модулеи" tabindex="-1">Статусы карточек и правила подключения модулей <a class="header-anchor" href="#статусы-карточек-и-правила-подключения-модулеи" aria-label="Permalink to &quot;Статусы карточек и правила подключения модулей&quot;">​</a></h2><p>В зависимости от текущей лицензии и типа расширения кнопка действия в карточке модуля принимает одно из четырех состояний:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Состояние кнопки</th><th style="text-align:center;">Значок интерфейса</th><th style="text-align:left;">Условия отображения</th><th style="text-align:left;">Что происходит при нажатии</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>«Подключить бесплатно»</strong></td><td style="text-align:center;">Загрузка</td><td style="text-align:left;">Модуль является бесплатным системным инструментом (например, <em>«Амбассадор»</em>).</td><td style="text-align:left;">Программа мгновенно привязывает модуль к вашей лицензии и открывает доступ в боковом меню без скачивания файлов.</td></tr><tr><td style="text-align:left;"><strong>«Купить за X ₽»</strong></td><td style="text-align:center;">Корзина</td><td style="text-align:left;">Профессиональный отраслевой инструмент с единоразовой оплатой.</td><td style="text-align:left;">Открывает защищенную страницу онлайн-оплаты в системном браузере. После подтверждения модуль активируется автоматически.</td></tr><tr><td style="text-align:left;"><strong>«Установлено»</strong></td><td style="text-align:center;">Галочка в круге</td><td style="text-align:left;">Модуль уже привязан к вашей лицензии или активен тариф разработчика.</td><td style="text-align:left;">Кнопка неактивна. Модуль готов к работе и отображается в блоке «Сквозные модули» бокового меню.</td></tr><tr><td style="text-align:left;"><strong>«Требуется лицензия»</strong></td><td style="text-align:center;">Замок</td><td style="text-align:left;">Программа работает в бесплатном ознакомительном режиме (триал на 20 продаж).</td><td style="text-align:left;">Кнопка заблокирована. Информирует о том, что сквозные модули доступны на коммерческих тарифах «Стандарт» и «ПРО».</td></tr></tbody></table><h3 id="пошаговое-руководство-подключение-бесплатного-модуля" tabindex="-1">Пошаговое руководство: подключение бесплатного модуля <a class="header-anchor" href="#пошаговое-руководство-подключение-бесплатного-модуля" aria-label="Permalink to &quot;Пошаговое руководство: подключение бесплатного модуля&quot;">​</a></h3><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>Шаг 1: Откройте каталог.</strong> Нажмите пункт <strong>«Маркетплейс модулей»</strong> в боковом меню приложения.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Шаг 2: Выберите инструмент.</strong> Найдите карточку модуля (например, «Амбассадор») и нажмите изумрудную кнопку <strong>«Подключить бесплатно»</strong>.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"></path><path d="m12 5 7 7-7 7"></path></svg></span><span><strong>Шаг 3: Мгновенная готовность.</strong> Система отправит криптографический запрос на сервер лицензирования, обновит токен в памяти и мгновенно выведет новый пункт в боковое меню. Перезапуск программы не требуется.</span></li></ul><h3 id="приобретение-платных-специализированных-модулеи" tabindex="-1">Приобретение платных специализированных модулей <a class="header-anchor" href="#приобретение-платных-специализированных-модулеи" aria-label="Permalink to &quot;Приобретение платных специализированных модулей&quot;">​</a></h3><p>ОмниКрафт ЕРП принципиально отвергает скрытые навязанные платежи. Платные расширения приобретаются <strong>единоразово и навсегда</strong>:</p><ol><li>Нажмите кнопку <strong>«Купить за X ₽»</strong> в карточке выбранного инструмента;</li><li>В системном веб-браузере откроется официальный защищенный платежный шлюз;</li><li>Произведите оплату любым удобным безналичным способом (банковской картой, через Систему быстрых платежей или по счету);</li><li>Сервер биллинга автоматически свяжет идентификатор модуля с вашим персональным кодом лицензии. Вернувшись в программу, вы сразу увидите статус <strong>«Установлено»</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Честная экономика ремесла</p><p>Вы никогда не переплачиваете за чужой функционал. Столярная мастерская оплачивает только раскрой пиломатериалов, студия полиграфии — расчет тиражей, а сервисный центр — интеграцию с базами запчастей. Базовое ядро программы остается доступным без дополнительных платежей.</p></div><hr><h2 id="инженерные-стандарты-безопасность-монолита-и-ленивая-загрузка" tabindex="-1">Инженерные стандарты: безопасность монолита и ленивая загрузка <a class="header-anchor" href="#инженерные-стандарты-безопасность-монолита-и-ленивая-загрузка" aria-label="Permalink to &quot;Инженерные стандарты: безопасность монолита и ленивая загрузка&quot;">​</a></h2><p>Большинство платформ с открытыми каталогами плагинов страдают от двух хронических болезней: риска заражения компьютера вредоносным кодом при скачивании сторонних скриптов и катастрофической потери скорости из-за утечек оперативной памяти.</p><p>В ОмниКрафт ЕРП эти угрозы полностью устранены на уровне компиляции:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Базовое ядро программы:</strong><br> Активы, Склад, ДДС, Баланс капитала — скомпилированы в бинарный файл и мгновенно готовы к работе. </div></li><li><span class="craft-list-bullet"></span><div><strong>Встроенный модуль «Амбассадор»:</strong><br> Скомпилирован в единый монолит, находится в ОЗУ только при открытии вкладки (0 МБ в покое). </div></li><li><span class="craft-list-bullet"></span><div><strong>Отраслевые модули расширения:</strong><br> Изолированные капсулы, лениво инициализируемые strictly on demand без внешних загрузок. </div></li></ul><h3 id="_1-концепция-встроенного-монолита" tabindex="-1">1. Концепция встроенного монолита <a class="header-anchor" href="#_1-концепция-встроенного-монолита" aria-label="Permalink to &quot;1. Концепция встроенного монолита&quot;">​</a></h3><p>Все официальные модули экосистемы ОмниКрафт ЕРП компилируются непосредственно в монолитный исполняемый файл приложения с помощью промышленного транслятора кода.</p><ul><li><strong>Никакого скачивания внешних файлов:</strong> При нажатии кнопки «Подключить» программа не загружает из интернета ненадежные динамические библиотеки (<code>.dll</code>) или скрипты (<code>.py</code>). Код модуля уже находится внутри программы и защищен цифровой подписью;</li><li><strong>100% защита от вредоносного ПО:</strong> Исключена любая возможность удаленного выполнения чужого кода через уязвимости плагинов;</li><li><strong>Нулевые конфликты с антивирусами:</strong> Системные защитники Windows Defender не выдают ложных срабатываний, так как структура файлов на диске остается монолитной и неизменной.</li></ul><h3 id="_2-ленивая-загрузка-нулевои-расход-памяти-в-покое" tabindex="-1">2. Ленивая загрузка (Нулевой расход памяти в покое) <a class="header-anchor" href="#_2-ленивая-загрузка-нулевои-расход-памяти-в-покое" aria-label="Permalink to &quot;2. Ленивая загрузка (Нулевой расход памяти в покое)&quot;">​</a></h3><p>Каждый модуль изолирован в независимую архитектурную капсулу.</p><p>Пока мастер не нажмет на название модуля в боковом меню, его графический интерфейс, служебные обработчики и фоновые процессы <strong>физически не инициализируются в оперативной памяти компьютера</strong>. Наличие в каталоге пяти или двадцати модулей не замедляет запуск программы ни на одну миллисекунду.</p><div class="info custom-block"><p class="custom-block-title">Физика учета: почему модули не замедляют работу</p><p>При старте ОмниКрафт ЕРП считывает только легковесные декларативные паспорта модулей (название, иконку и признак глобальности). Полноценное развертывание таблиц и логики происходит строго по требованию в момент первого перехода во вкладку.</p></div><hr><h2 id="изоляция-данных-глобальные-модули-против-локальных-цехов" tabindex="-1">Изоляция данных: глобальные модули против локальных цехов <a class="header-anchor" href="#изоляция-данных-глобальные-модули-против-локальных-цехов" aria-label="Permalink to &quot;Изоляция данных: глобальные модули против локальных цехов&quot;">​</a></h2><p>В модульной системе ОмниКрафт ЕРП действует строгое разделение ответственности баз данных:</p><table class="craft-matrix-table"><thead><tr><th style="width:35%;">Файл базы данных</th><th style="width:25%;">Область действия</th><th style="width:40%;">Хранимые данные</th></tr></thead><tbody><tr><td><code>global_extensions.db</code></td><td><strong>Глобальный уровень</strong></td><td>Сквозной маркетинг, партнёрские ссылки, кампании и связи поверх всех пространств.</td></tr><tr><td><code>workspace.db</code></td><td><strong>Локальный цех</strong></td><td>Склад сырья, парк станков, касса ДДС и клиентские заказы конкретного дела.</td></tr></tbody></table><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg></span><span><strong>Сквозные глобальные модули:</strong> Модули уровня «Амбассадор» или централизованного управления рекламой хранят свои таблицы в отдельном системном файле <code>global_extensions.db</code>. Они работают поверх всех ваших мастерских.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" x2="12" y1="15" y2="3"></line></svg></span><span><strong>Абсолютная защита от сброса цеха:</strong> Если вы решили переформатировать столярную мастерскую, очистить операционную историю кассы или заархивировать старое направление, глобальные модули не теряют ни одной строчки. Ваши реферальные ссылки, история рекламных кампаний и наработанные партнерские связи останутся в полной сохранности.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M3 9h18"></path><path d="M9 21V9"></path></svg></span><span><strong>Отраслевые локальные модули:</strong> Будущие расширения, работающие с технологическими картами конкретного производства (раскрой, нормы расхода), сохраняют свои данные непосредственно внутри базы активного рабочего пространства с системным префиксом <code>mod_*</code>.</span></li></ul><div class="tip custom-block"><p class="custom-block-title">Преемственность партнерских связей</p><p>Вы можете вести производство кожаных изделий, параллельно открыть сервис заточки инструмента и закрыть неудачный торговый эксперимент. База модуля «Амбассадор» продолжит сквозной учет всех привлеченных клиентов и бонусов без привязки к судьбе отдельных мастерских.</p></div><hr><h2 id="тарифная-политика-доступность-модулеи" tabindex="-1">Тарифная политика: доступность модулей <a class="header-anchor" href="#тарифная-политика-доступность-модулеи" aria-label="Permalink to &quot;Тарифная политика: доступность модулей&quot;">​</a></h2><p>Возможности работы с каталогом расширений зависят от типа активной коммерческой лицензии программы:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Тарифный план</th><th style="text-align:center;">Доступ к Маркетплейсу</th><th style="text-align:center;">Бесплатные модули</th><th style="text-align:center;">Докупка платных модулей</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Бесплатный (Ознакомительный)</strong></td><td style="text-align:center;">Просмотр каталога</td><td style="text-align:center;">Недоступно (Замок)</td><td style="text-align:center;">Недоступно (Требуется лицензия)</td></tr><tr><td style="text-align:left;"><strong>Стандартный</strong></td><td style="text-align:center;">Полный доступ</td><td style="text-align:center;">Подключение в 1 клик</td><td style="text-align:center;">Доступна единоразовая покупка</td></tr><tr><td style="text-align:left;"><strong>ПРО (Профессиональный)</strong></td><td style="text-align:center;">Полный доступ</td><td style="text-align:center;">Подключение в 1 клик</td><td style="text-align:center;">Доступна единоразовая покупка</td></tr><tr><td style="text-align:left;"><strong>ПРО+ (Лицензия разработчика)</strong></td><td style="text-align:center;">Полный доступ</td><td style="text-align:center;">Автоматически активно</td><td style="text-align:center;">Автоматически разблокированы</td></tr></tbody></table><hr><h2 id="вопросы-и-ответы-мастера" tabindex="-1">Вопросы и ответы мастера <a class="header-anchor" href="#вопросы-и-ответы-мастера" aria-label="Permalink to &quot;Вопросы и ответы мастера&quot;">​</a></h2><h3 id="требуется-ли-постоянное-подключение-к-интернету-для-работы-с-модулем" tabindex="-1">Требуется ли постоянное подключение к интернету для работы с модулем? <a class="header-anchor" href="#требуется-ли-постоянное-подключение-к-интернету-для-работы-с-модулем" aria-label="Permalink to &quot;Требуется ли постоянное подключение к интернету для работы с модулем?&quot;">​</a></h3><p>Нет. Интернет необходим только на несколько секунд в момент первого подключения или покупки модуля, чтобы синхронизировать криптографический ключ с сервером. Вся последующая ежедневная работа с модулем (составление кампаний, ведение ссылок, расчеты) протекает <strong>на 100% автономно в режиме офлайн</strong>.</p><h3 id="что-произоидет-с-подключенными-модулями-при-переносе-программы-на-другои-компьютер" tabindex="-1">Что произойдет с подключенными модулями при переносе программы на другой компьютер? <a class="header-anchor" href="#что-произоидет-с-подключенными-модулями-при-переносе-программы-на-другои-компьютер" aria-label="Permalink to &quot;Что произойдет с подключенными модулями при переносе программы на другой компьютер?&quot;">​</a></h3><p>Все ваши права зафиксированы за вашим персональным лицензионным ключом. При установке ОмниКрафт ЕРП на новый рабочий ноутбук достаточно ввести свой ключ в настройках программы: система мгновенно восстановит доступ ко всем ранее подключенным и купленным модулям.</p><h3 id="можно-ли-скрыть-подключенныи-модуль-из-меню-если-он-временно-не-используется" tabindex="-1">Можно ли скрыть подключенный модуль из меню, если он временно не используется? <a class="header-anchor" href="#можно-ли-скрыть-подключенныи-модуль-из-меню-если-он-временно-не-используется" aria-label="Permalink to &quot;Можно ли скрыть подключенный модуль из меню, если он временно не используется?&quot;">​</a></h3><p>Да. В настройках интерфейса бокового меню вы можете регулировать видимость неиспользуемых разделов, сохраняя рабочий стол в идеальном порядке. При этом накопленные данные модуля в базе данных не удаляются.</p>',51))])}const m=a(c,[["render",g]]);export{k as __pageData,m as default};
